  const ranked = [...sectors].sort((x, y) => x.delta_s - y.delta_s);
  const line = (sector) => `${sector.start_m.toFixed(0)}\u2013${sector.end_m.toFixed(0)} m: ${signed(sector.delta_s)} s`;
